"""Record source-qualified Djinn findings without changing product code."""
from pathlib import Path
import hashlib
import json

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]


def load(name):
    return json.loads((HERE / name).read_text(encoding="utf-8"))


def save(name, value):
    (HERE / name).write_text(json.dumps(value, indent=2) + "\n", encoding="utf-8")


def merge_by_id(existing, additions):
    indexed = {item["id"]: item for item in additions}
    return [indexed.pop(item["id"], item) for item in existing] + list(indexed.values())


